    fake.register_user(id: admin.id, company_id: company.id, role: "admin")
    fake.register_user(id: colleague.id, company_id: company.id, role: "employee")
    fake.register_project(id: project.id, company_id: company.id)
    route_timekeeping_to_fake(fake, base_url:)
    TimekeepingOwnership.current.update!(owner: "timekeeping", generation: 2, handoff_step: nil)
    fake.generation = 2
  end

  # "The CLI keeps its own-entries scope: the lookup is restricted to `user_id` equal to the actor and to the current company."
  # "A forwarded CLI update of another user's entry gets 404."
  # The caller is an admin, whom a company-wide lookup would let edit a colleague's entry; only the
  # own-entries scope refuses it.
  it "forwards an admin's CLI update of their own entry but answers 404 and forwards nothing for a colleague's entry in the same company" do
    own_entry_id = fake.add_entry(company_id: company.id, user_id: admin.id, project_id: project.id)["id"]
    colleague_entry_id = fake.add_entry(company_id: company.id, user_id: colleague.id, project_id: project.id)["id"]
    update_params = {
      timesheet_entry: { project_id: project.id, duration_minutes: 45, work_date: Date.current.iso8601, note: "Edited from CLI" }
    }

    send_request :patch, api_v1_cli_timesheet_entry_path(own_entry_id), params: update_params,
                                                                        headers: cli_auth_headers(cli_token)

    expect(response).to have_http_status(:ok)
    expect(fake.stored_entry(own_entry_id)["note"]).to eq("Edited from CLI")

    patches_before = fake.requests.count { |request| request[:method] == "PATCH" }
    send_request :patch, api_v1_cli_timesheet_entry_path(colleague_entry_id), params: update_params,
                                                                              headers: cli_auth_headers(cli_token)

    expect(response).to have_http_status(:not_found)
    expect(fake.requests.count { |request| request[:method] == "PATCH" }).to eq(patches_before)
    expect(fake.stored_entry(colleague_entry_id)["note"]).not_to eq("Edited from CLI")
    expect(fake.stored_entry(colleague_entry_id)["duration"]).to eq(60.0)
  end
end
